def build():
    out = []
    for m, cards in CARDS.items():
        for i, (q, a) in enumerate(cards):
            out.append({'id': '%s-k%d' % (m, i + 1), 'm': m, 'q': q, 'a': a.inline(), 'src': [a.ref]})
    return push_js('cards', out)
